files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --success: #4ecca3;
  --border-radius: 8px;
  --pixel-size: 4px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 3px solid var(--secondary);
  border-radius: var(--border-radius);
  padding: 24px;
  width: 100%;
  max-width: 600px;
  box-shadow: 0 0 0 3px var(--bg), 0 0 0 6px var(--secondary);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 20px;
  text-align: center;
  color: var(--primary);
  text-shadow: 2px 2px 0 var(--secondary);
  letter-spacing: 1px;
}

.habit-form {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.habit-form input {
  flex: 1 1 200px;
  padding: 12px 16px;
  font-size: 1rem;
  background: var(--bg);
  border: 2px solid var(--secondary);
  border-radius: var(--border-radius);
  color: var(--text);
  outline: none;
  transition: border-color 0.15s;
}

.habit-form input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px var(--primary);
}

.habit-form input::placeholder {
  color: var(--text-muted);
}

.btn-add {
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  background: var(--primary);
  color: var(--text);
  border: 2px solid var(--primary);
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  white-space: nowrap;
}

.btn-add:hover {
  background: #c73e54;
  border-color: #c73e54;
}

.btn-add:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn-add:active {
  transform: scale(0.96);
}

.habit-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.habit-item {
  background: var(--bg);
  border: 2px solid var(--secondary);
  border-radius: var(--border-radius);
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.habit-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.habit-name {
  font-weight: 600;
  font-size: 1.1rem;
  word-break: break-word;
}

.habit-streak {
  font-size: 0.9rem;
  color: var(--success);
  font-weight: 600;
  white-space: nowrap;
}

.habit-streak::before {
  content: '🔥 ';
}

.day-toggles {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.day-btn {
  width: 40px;
  height: 40px;
  font-size: 0.85rem;
  font-weight: 700;
  background: var(--secondary);
  color: var(--text-muted);
  border: 2px solid var(--secondary);
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.1s;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  line-height: 1;
}

.day-btn:hover {
  background: #1a4a7a;
  border-color: #1a4a7a;
  color: var(--text);
}

.day-btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.day-btn:active {
  transform: scale(0.9);
}

.day-btn.done {
  background: var(--success);
  border-color: var(--success);
  color: var(--bg);
}

.day-btn.done:hover {
  background: #3db88a;
  border-color: #3db88a;
}

.btn-delete {
  align-self: flex-end;
  padding: 6px 12px;
  font-size: 0.85rem;
  background: transparent;
  color: var(--text-muted);
  border: 2px solid var(--secondary);
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.btn-delete:hover {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--text);
}

.btn-delete:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.btn-delete:active {
  transform: scale(0.96);
}

.empty-message {
  text-align: center;
  color: var(--text-muted);
  padding: 24px 0;
  font-style: italic;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .habit-form {
    flex-direction: column;
  }
  .habit-form input {
    flex: 1 1 auto;
  }
  .btn-add {
    width: 100%;
  }
  .day-btn {
    width: 36px;
    height: 36px;
    font-size: 0.75rem;
  }
}

(function() {
  'use strict';

  const STORAGE_KEY = 'pixelHabitTracker';
  const DAYS = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];

  let habits = loadHabits();

  const form = document.getElementById('habit-form');
  const input = document.getElementById('habit-name');
  const list = document.getElementById('habit-list');
  const emptyMsg = document.getElementById('empty-message');

  function loadHabits() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : [];
    } catch (e) {
      return [];
    }
  }

  function saveHabits() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(habits));
    } catch (e) {
      // localStorage unavailable; app still works in memory
    }
  }

  function calculateStreak(days) {
    let streak = 0;
    for (let i = 6; i >= 0; i--) {
      if (days[i]) streak++;
      else break;
    }
    return streak;
  }

  function render() {
    list.innerHTML = '';
    if (habits.length === 0) {
      emptyMsg.style.display = 'block';
      return;
    }
    emptyMsg.style.display = 'none';

    habits.forEach((habit, index) => {
      const li = document.createElement('li');
      li.className = 'habit-item';

      const header = document.createElement('div');
      header.className = 'habit-header';

      const nameSpan = document.createElement('span');
      nameSpan.className = 'habit-name';
      nameSpan.textContent = habit.name;

      const streakSpan = document.createElement('span');
      streakSpan.className = 'habit-streak';
      streakSpan.textContent = calculateStreak(habit.days) + ' day' + (calculateStreak(habit.days) === 1 ? '' : 's');

      header.appendChild(nameSpan);
      header.appendChild(streakSpan);

      const toggles = document.createElement('div');
      toggles.className = 'day-toggles';
      toggles.setAttribute('role', 'group');
      toggles.setAttribute('aria-label', 'Days for ' + habit.name);

      DAYS.forEach((day, dayIndex) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'day-btn' + (habit.days[dayIndex] ? ' done' : '');
        btn.textContent = day;
        btn.setAttribute('aria-label', day + ' for ' + habit.name + (habit.days[dayIndex] ? ', done' : ', not done'));
        btn.setAttribute('aria-pressed', habit.days[dayIndex] ? 'true' : 'false');
        btn.addEventListener('click', () => {
          habit.days[dayIndex] = !habit.days[dayIndex];
          saveHabits();
          render();
        });
        toggles.appendChild(btn);
      });

      const deleteBtn = document.createElement('button');
      deleteBtn.type = 'button';
      deleteBtn.className = 'btn-delete';
      deleteBtn.textContent = 'Delete';
      deleteBtn.setAttribute('aria-label', 'Delete habit ' + habit.name);
      deleteBtn.addEventListener('click', () => {
        habits.splice(index, 1);
        saveHabits();
        render();
      });

      li.appendChild(header);
      li.appendChild(toggles);
      li.appendChild(deleteBtn);
      list.appendChild(li);
    });
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = input.value.trim();
    if (!name) return;
    habits.push({ name: name, days: [false, false, false, false, false, false, false] });
    input.value = '';
    saveHabits();
    render();
    input.focus();
  });

  render();
})();
